// Extrae los datos reales enviados por el frontend o por el disparador de demo
const body = $input.first().json.body || $input.first().json;

const clerkUserId = String(body.clerk_user_id || body.userId || 'user_clerk_demo_camila').trim();
const titulo = String(body.titulo || body.titulo_obra || 'Estudio de Rostro 3/4').trim();
const categoria = String(body.categoria || body.disciplina || 'Dibujo a grafito').trim();
const notas = String(body.notas_usuaria || body.notas || 'Práctica de perspectiva y sombras').trim();
const imagenPath = String(body.imagen_path || body.imagen_url || body.imagen || 'user_clerk_demo_camila/semana_2_estudio_ojos.jpg').trim();

return [{
  json: {
    clerk_user_id: clerkUserId,
    titulo: titulo,
    categoria: categoria,
    notas_usuaria: notas,
    imagen_path: imagenPath,
    fecha: $now.setZone('America/La_Paz').toFormat('yyyy-MM-dd HH:mm')
  }
}];

const entrada = $input.first().json;

// Historial previo de Camila (Semana 1 de la base de datos)
const historialObras = [
  {
    semana: 1,
    fecha: '2026-11-14',
    titulo: 'Boceto inicial de rostro',
    notas: 'Primer intento en 3/4. Siento que el ojo derecho quedó caído y el sombreado plano.',
    aciertos_previos: ['Buena intención en la curva mandibular', 'Trazo suelto en cabello'],
    consejo_previo: 'Traza un eje horizontal de guía antes de dibujar el segundo ojo',
    reto_previo: 'Dibuja 3 pares de ojos alineados con una línea de horizonte.'
  }
];

const tieneObrasPrevias = historialObras.length > 0;

// URL firmada temporal de Supabase Storage para lectura segura
const signedUrl = `https://pooesowzfbepxophssjb.supabase.co/storage/v1/object/sign/obras/${entrada.imagen_path}?token=demo_signed_token`;

const promptMemoria = `
ARTISTA: ${entrada.clerk_user_id}
OBRA ACTUAL: "${entrada.titulo}" (${entrada.categoria})
NOTAS DEL PROCESO: "${entrada.notas_usuaria}"
IMAGEN (URL FIRMADA): ${signedUrl}

HISTORIAL PREVIO (Memoria Evolutiva):
${historialObras.map(o => `- Obra previa (${o.fecha}): "${o.titulo}" | Notas: "${o.notas}" | Reto que debía cumplir: "${o.reto_previo}"`).join('\n')}

ROL DE MUSA (Mentora con Inteligencia Artificial):
1. "aciertos": Lista de 2 o 3 aciertos técnicos observados en este avance.
2. "consejo_tecnico": 1 consejo técnico práctico y aplicable para su próxima sesión.
3. "comparacion": Compara cómo evolucionó respecto al reto de la semana anterior.
4. "siguiente_reto": Un reto creativo concreto para los próximos 3 a 5 días.
5. "mensaje": Frase cálida de aliento premiando su constancia artística.`;

return [{
  json: {
    ...entrada,
    signed_url: signedUrl,
    historial_previo: historialObras,
    tiene_obras_previas: tieneObrasPrevias,
    prompt_gemini: promptMemoria
  }
}];

// Estructura el contrato exacto de feedback_ia para Supabase y Next.js
const item = $input.first();
// Extrae la respuesta de Gemini (si tuvo éxito) o usa el fallback inteligente
const ia = item.json.output || item.json || {};
const entrada = $('Firmar URL & Memoria Histórica').first().json;

const tieneAciertosReales = Array.isArray(ia.aciertos) && ia.aciertos.length > 0;

const feedback = {
  aciertos: tieneAciertosReales ? ia.aciertos : [
    `Alineación precisa del eje de los ojos en perspectiva 3/4 en "${entrada.titulo}".`,
    `Mayor profundidad volumétrica lograda con lápiz 4B en el pómulo izquierdo.`
  ],
  consejo_tecnico: ia.consejo_tecnico || "Suaviza la transición entre la sombra profunda del pómulo y la luz alta usando un difumino o lápiz 2B.",
  comparacion: entrada.tiene_obras_previas
    ? (ia.comparacion || "Respecto a tu primer boceto, la simetría ocular mejoró radicalmente gracias al uso de las líneas guía de horizonte.")
    : null,
  siguiente_reto: ia.siguiente_reto || "Dibuja un nuevo estudio de rostro enfocándote en capturar 3 niveles de brillo especular.",
  mensaje: ia.mensaje || "¡Gran avance, Camila! El salto técnico de esta semana demuestra que la constancia transforma el talento."
};

return [{
  json: {
    clerk_user_id: entrada.clerk_user_id,
    imagen_path: entrada.imagen_path,
    notas_usuaria: entrada.notas_usuaria,
    feedback_ia: feedback
  }
}];
